// Generated by `mise run charts` from charts/*.scxml and spec/work-packet.xsd:
// do not edit. test/charts.test.mjs checks it against the files.

/** Each chart's file name → its SCXML text. */
export const charts = {
  "annotation.scxml": "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!--\n  One annotation: a piece of the page's text, the user's note about it, the\n  model's rewrites, and the user's decision. The actor reaches the world only\n  through four I/O processors:\n\n    model  rewrite        → model.reply {text, rewrites, note, audiences, for, sources?, thoughts?, seconds?} | model.error {message}\n           transcribe     → model.transcript {text} | model.error {message}   (a spoken message: the clip's id)\n    settings audience     → audience.saved {ids: {name: id}} | audience.refused {message}\n    page   locate         → page.located {found}\n           preview        → page.previewed {ok}   (reveal: the page scrolls to it, a kept one restored does not)\n           revert         (no answer)\n    store  save, delete   (no answer)\n    ui     changed        its record, after every change\n           removed        {id, page}, when it is deleted\n\n  A spoken message (`ask` with a clip) is transcribed first: the transcript\n  is the user's message, and the annotation goes on as with a typed one.\n  The audience calls of a reply (`define_audience`, `use_audiences`) go to\n  the `settings` processor; the model's message names them (`audiences`).\n  `audiences` holds the names of the audiences the last rewrites were\n  written for (the reply's `for`), which the export names.\n\n  A finding of a reading (charts/reading.scxml) is an annotation of\n  source 'audience' whose `finding` is {audienceID, kind, explanation,\n  need?, section?, item?}; its proposed rewrite is its first suggestion.\n  An accepted item of the page's revision plan (charts/plan.scxml) is an\n  annotation of source 'plan' whose `plan` is {itemID, action, needs,\n  criteria, target, where}: the plan's text its first suggestion ('' for\n  a cut), previewed and kept as any other; the export lists its criteria.\n\n  One with no `anchor` is page-level: what the page lacks, never located\n  or previewed. A newer reading of the audience sends `retire`: a finding\n  the reviewer has not touched (draft or suggested, no note, no message,\n  no text of their own) deletes itself.\n\n  Rewrites side by side: an `ask` or `suggest` carries the page's active\n  audiences (`audienceIDs`, kept as `active`; `active` is a spawn's param\n  too, for a note that asks at once). With two or more, and no finding (a\n  finding is one audience's), the rewrite request is per audience\n  (`request.audienceIDs`): the model writes one rewrite for each and maybe\n  one that serves them all, and each suggestion keeps its `audienceID`\n  (null: for everyone). With one or none, a suggestion has no\n  `audienceID`, as before.\n\n  A suggestion's `after` is the number of messages before it: the panel\n  shows it after the message that brought it. The record is the datamodel\n  but `request` and `clip`. `state` names the decision for\n  the store; an actor spawned with a stored record starts from it.\n-->\n<scxml xmlns=\"http://www.w3.org/2005/07/scxml\" version=\"1.0\"\n       datamodel=\"ecmascript\" name=\"annotation\" initial=\"live\">\n  <datamodel>\n    <data id=\"id\"/>\n    <data id=\"page\"/>\n    <data id=\"lang\" expr=\"'en'\"/>\n    <data id=\"original\" expr=\"''\"/>\n    <data id=\"anchor\" expr=\"null\"/>\n    <data id=\"anchorFound\" expr=\"true\"/>\n    <data id=\"note\" expr=\"''\"/>\n    <data id=\"source\" expr=\"'typed'\"/>\n    <data id=\"suggestions\" expr=\"[]\"/>\n    <data id=\"chosenID\" expr=\"null\"/>\n    <data id=\"messages\" expr=\"[]\"/>\n    <data id=\"error\" expr=\"null\"/>\n    <data id=\"createdAt\" expr=\"null\"/>\n    <data id=\"updatedAt\" expr=\"null\"/>\n    <data id=\"state\" expr=\"'new'\"/>\n    <data id=\"audiences\" expr=\"[]\"/>\n    <!-- a reading's finding: {audienceID, kind, explanation, need?, section?, item?} -->\n    <data id=\"finding\" expr=\"null\"/>\n    <!-- an accepted item of the page's plan (charts/plan.scxml): {itemID, action, needs, criteria, target, where} -->\n    <data id=\"plan\" expr=\"null\"/>\n    <!-- what the next model request carries besides the messages: {more} -->\n    <data id=\"request\" expr=\"null\"/>\n    <!-- the page's active audiences at the last ask or suggest (or the spawn) -->\n    <data id=\"active\" expr=\"[]\"/>\n    <!-- the id of the clip being transcribed (the core keeps the audio) -->\n    <data id=\"clip\" expr=\"null\"/>\n  </datamodel>\n\n  <script>\n    // The model's message of a reply: its words, the audience calls it made,\n    // the web pages it was grounded on and the summary of its thinking. A\n    // helper of the chart.\n    function reply(data) {\n      var m = { role: 'model', text: data.text || 'No change proposed.', at: new Date().toISOString() };\n      var named = (data.audiences || []).flatMap((c) => (c.action === 'use' ? c.names : [c.name]).map((name) => ({ name: name, action: c.action })));\n      if (named.length) m.audiences = named;\n      if (data.sources &amp;&amp; data.sources.length) m.sources = data.sources;\n      if (data.thoughts) m.thoughts = data.thoughts;\n      if (data.seconds) m.seconds = data.seconds;\n      return m;\n    }\n\n    // What the next rewrite request carries: {more} for more alternatives,\n    // {audienceIDs} to write one rewrite per active audience (two or more,\n    // and not a finding, which is one audience's); null for neither.\n    function requestOf(more, ids, found) {\n      var r = {};\n      if (more) r.more = true;\n      if (!found &amp;&amp; ids &amp;&amp; ids.length > 1) r.audienceIDs = ids;\n      return Object.keys(r).length ? r : null;\n    }\n\n    // A rewrite of a reply as a suggestion; a per-audience one keeps its audienceID.\n    function suggestion(r, n, after) {\n      var s = { id: 's' + n, text: r.replacement, rationale: r.rationale || '', after: after };\n      if (r.audienceID !== undefined) s.audienceID = r.audienceID;\n      return s;\n    }\n  </script>\n\n  <state id=\"live\" initial=\"restore\">\n    <!-- Every state raises `changed`: the record goes to the panel and to the store. -->\n    <transition event=\"changed\">\n      <assign location=\"updatedAt\" expr=\"new Date().toISOString()\"/>\n      <send type=\"ui\" event=\"changed\" namelist=\"id page lang original anchor anchorFound note source suggestions chosenID messages error createdAt updatedAt state audiences finding plan\"/>\n      <send type=\"store\" event=\"save\" namelist=\"id page lang original anchor anchorFound note source suggestions chosenID messages error createdAt updatedAt state audiences finding plan\"/>\n    </transition>\n    <transition event=\"note\">\n      <assign location=\"note\" expr=\"_event.data.text\"/>\n      <raise event=\"changed\"/>\n    </transition>\n    <transition event=\"page.located\">\n      <assign location=\"anchorFound\" expr=\"_event.data.found\"/>\n      <raise event=\"changed\"/>\n    </transition>\n    <transition event=\"page.previewed\">\n      <assign location=\"anchorFound\" expr=\"_event.data.ok\"/>\n      <raise event=\"changed\"/>\n    </transition>\n    <transition event=\"delete\" target=\"deleted\"/>\n    <!-- the settings processor's answers: a saved audience's id on its chip; a refusal is the error -->\n    <transition event=\"audience.saved\">\n      <assign location=\"messages\" expr=\"messages.map((m) => m.audiences ? Object.assign({}, m, { audiences: m.audiences.map((a) => (!a.id &amp;&amp; _event.data.ids[a.name] ? Object.assign({}, a, { id: _event.data.ids[a.name] }) : a)) }) : m)\"/>\n      <raise event=\"changed\"/>\n    </transition>\n    <transition event=\"audience.refused\">\n      <assign location=\"error\" expr=\"_event.data.message\"/>\n      <raise event=\"changed\"/>\n    </transition>\n\n    <!-- A new actor, or one the store gave back: go to the state it was in. -->\n    <state id=\"restore\">\n      <onentry>\n        <if cond=\"!createdAt\"><assign location=\"createdAt\" expr=\"new Date().toISOString()\"/></if>\n      </onentry>\n      <transition cond=\"state === 'kept'\" target=\"kept\">\n        <send type=\"page\" event=\"preview\">\n          <content expr=\"({ id, anchor, text: suggestions.find((s) => s.id === chosenID).text })\"/>\n        </send>\n      </transition>\n      <transition cond=\"state === 'new' &amp;&amp; note\" target=\"asking\">\n        <assign location=\"messages\" expr=\"[{ role: 'user', text: note, at: createdAt }]\"/>\n        <assign location=\"request\" expr=\"requestOf(false, active, finding)\"/>\n      </transition>\n      <!-- page-level: nothing on the page to find -->\n      <transition cond=\"!anchor\" target=\"open\"/>\n      <transition target=\"open\">\n        <send type=\"page\" event=\"locate\"><content expr=\"({ id, anchor })\"/></send>\n      </transition>\n    </state>\n\n    <!-- Waiting for the user: ask, edit, preview or dismiss. -->\n    <state id=\"open\" initial=\"opening\">\n      <state id=\"opening\">\n        <transition cond=\"state === 'failed'\" target=\"failed\"/>\n        <transition cond=\"state === 'dismissed'\" target=\"dismissed\"/>\n        <transition cond=\"suggestions.length > 0\" target=\"suggested\"/>\n        <transition target=\"draft\"/>\n      </state>\n      <state id=\"draft\">\n        <onentry><assign location=\"state\" expr=\"'draft'\"/><raise event=\"changed\"/></onentry>\n        <transition event=\"retire\" cond=\"source === 'audience' &amp;&amp; !note &amp;&amp; !messages.length &amp;&amp; !suggestions.some((s) => s.own)\" target=\"deleted\"/>\n      </state>\n      <state id=\"suggested\">\n        <onentry><assign location=\"state\" expr=\"'suggested'\"/><raise event=\"changed\"/></onentry>\n        <transition event=\"retire\" cond=\"source === 'audience' &amp;&amp; !note &amp;&amp; !messages.length &amp;&amp; !suggestions.some((s) => s.own)\" target=\"deleted\"/>\n      </state>\n      <state id=\"failed\">\n        <onentry><assign location=\"state\" expr=\"'failed'\"/><raise event=\"changed\"/></onentry>\n      </state>\n      <state id=\"dismissed\">\n        <onentry><assign location=\"state\" expr=\"'dismissed'\"/><raise event=\"changed\"/></onentry>\n        <transition event=\"reopen\" target=\"opening\">\n          <assign location=\"state\" expr=\"'open'\"/>\n          <assign location=\"error\" expr=\"null\"/>\n        </transition>\n        <!-- a dismissed annotation takes no other command until it is reopened -->\n        <transition event=\"ask suggest edit preview dismiss\"/>\n      </state>\n\n      <transition event=\"ask\" cond=\"_event.data.clip\" target=\"transcribing\">\n        <assign location=\"active\" expr=\"(_event.data &amp;&amp; _event.data.audienceIDs) || []\"/>\n        <assign location=\"clip\" expr=\"_event.data.clip\"/>\n      </transition>\n      <transition event=\"ask\" target=\"asking\">\n        <assign location=\"active\" expr=\"(_event.data &amp;&amp; _event.data.audienceIDs) || []\"/>\n        <assign location=\"messages\" expr=\"messages.concat([{ role: 'user', text: _event.data.text, at: new Date().toISOString() }])\"/>\n        <assign location=\"request\" expr=\"requestOf(false, active, finding)\"/>\n      </transition>\n      <transition event=\"suggest\" target=\"asking\">\n        <assign location=\"active\" expr=\"(_event.data &amp;&amp; _event.data.audienceIDs) || []\"/>\n        <assign location=\"request\" expr=\"requestOf(true, active, finding)\"/>\n      </transition>\n      <!-- page-level: the reviewer's own text to add, never previewed -->\n      <transition event=\"edit\" cond=\"!anchor\" target=\"suggested\">\n        <assign location=\"suggestions\" expr=\"suggestions.concat([{ id: 's' + (suggestions.length + 1), text: _event.data.text, rationale: 'Your own text', own: true, after: messages.length }])\"/>\n      </transition>\n      <transition event=\"edit\" target=\"previewing\">\n        <assign location=\"suggestions\" expr=\"suggestions.concat([{ id: 's' + (suggestions.length + 1), text: _event.data.text, rationale: 'Your own text', own: true, after: messages.length }])\"/>\n        <assign location=\"chosenID\" expr=\"suggestions[suggestions.length - 1].id\"/>\n      </transition>\n      <transition event=\"preview\" cond=\"anchor &amp;&amp; suggestions.some((s) => s.id === _event.data.suggestionID)\" target=\"previewing\">\n        <assign location=\"chosenID\" expr=\"_event.data.suggestionID\"/>\n      </transition>\n      <transition event=\"dismiss\" target=\"dismissed\"/>\n    </state>\n\n    <!-- A spoken message: the model writes down what was said, and that is the message. -->\n    <state id=\"transcribing\">\n      <onentry>\n        <assign location=\"state\" expr=\"'transcribing'\"/>\n        <assign location=\"error\" expr=\"null\"/>\n        <raise event=\"changed\"/>\n        <send type=\"model\" event=\"transcribe\" namelist=\"id clip\"/>\n      </onentry>\n      <onexit><assign location=\"clip\" expr=\"null\"/></onexit>\n      <transition event=\"model.transcript\" cond=\"String(_event.data.text || '').trim()\" target=\"asking\">\n        <assign location=\"messages\" expr=\"messages.concat([{ role: 'user', text: String(_event.data.text).trim(), at: new Date().toISOString(), spoken: true }])\"/>\n        <assign location=\"request\" expr=\"requestOf(false, active, finding)\"/>\n      </transition>\n      <transition event=\"model.transcript\" target=\"opening\">\n        <assign location=\"error\" expr=\"'Nothing was heard.'\"/>\n      </transition>\n      <transition event=\"model.error\" target=\"failed\">\n        <assign location=\"error\" expr=\"_event.data.message\"/>\n      </transition>\n      <transition event=\"error.communication\" target=\"failed\">\n        <assign location=\"error\" expr=\"'The model could not be reached.'\"/>\n      </transition>\n    </state>\n\n    <!-- The model is working on it. -->\n    <state id=\"asking\">\n      <onentry>\n        <assign location=\"state\" expr=\"'asking'\"/>\n        <assign location=\"error\" expr=\"null\"/>\n        <raise event=\"changed\"/>\n        <send type=\"model\" event=\"rewrite\" namelist=\"id page original note messages suggestions request finding anchor\"/>\n      </onentry>\n      <transition event=\"model.reply\" target=\"opening\">\n        <assign location=\"messages\" expr=\"messages.concat([reply(_event.data)])\"/>\n        <foreach array=\"_event.data.audiences || []\" item=\"call\">\n          <send type=\"settings\" event=\"audience\"><content expr=\"call\"/></send>\n        </foreach>\n        <if cond=\"_event.data.for &amp;&amp; _event.data.for.length &amp;&amp; (_event.data.rewrites || []).length\">\n          <assign location=\"audiences\" expr=\"_event.data.for\"/>\n        </if>\n        <assign location=\"suggestions\" expr=\"suggestions.concat((_event.data.rewrites || []).map((r, i) => suggestion(r, suggestions.length + i + 1, messages.length)))\"/>\n        <if cond=\"_event.data.note &amp;&amp; !note\"><assign location=\"note\" expr=\"_event.data.note\"/></if>\n        <assign location=\"request\" expr=\"null\"/>\n      </transition>\n      <transition event=\"model.error\" target=\"failed\">\n        <assign location=\"error\" expr=\"_event.data.message\"/>\n        <assign location=\"request\" expr=\"null\"/>\n      </transition>\n      <transition event=\"error.communication\" target=\"failed\">\n        <assign location=\"error\" expr=\"'The model could not be reached.'\"/>\n        <assign location=\"request\" expr=\"null\"/>\n      </transition>\n    </state>\n\n    <!-- The page shows the chosen suggestion in place of the original. -->\n    <state id=\"previewing\">\n      <onentry>\n        <assign location=\"state\" expr=\"'previewing'\"/>\n        <assign location=\"error\" expr=\"null\"/>\n        <raise event=\"changed\"/>\n        <send type=\"page\" event=\"preview\">\n          <content expr=\"({ id, anchor, text: suggestions.find((s) => s.id === chosenID).text, reveal: true })\"/>\n        </send>\n      </onentry>\n      <transition event=\"page.previewed\" cond=\"!_event.data.ok\" target=\"suggested\">\n        <assign location=\"anchorFound\" expr=\"false\"/>\n        <assign location=\"chosenID\" expr=\"null\"/>\n        <assign location=\"error\" expr=\"'The text is no longer on the page.'\"/>\n      </transition>\n      <transition event=\"preview\" cond=\"anchor &amp;&amp; suggestions.some((s) => s.id === _event.data.suggestionID)\" target=\"previewing\">\n        <assign location=\"chosenID\" expr=\"_event.data.suggestionID\"/>\n      </transition>\n      <transition event=\"edit\" target=\"previewing\">\n        <assign location=\"suggestions\" expr=\"suggestions.concat([{ id: 's' + (suggestions.length + 1), text: _event.data.text, rationale: 'Your own text', own: true, after: messages.length }])\"/>\n        <assign location=\"chosenID\" expr=\"suggestions[suggestions.length - 1].id\"/>\n      </transition>\n      <transition event=\"keep\" target=\"kept\"/>\n      <!-- Anything else puts the original back first. -->\n      <transition event=\"undo\" target=\"suggested\">\n        <send type=\"page\" event=\"revert\"><content expr=\"({ id })\"/></send>\n        <assign location=\"chosenID\" expr=\"null\"/>\n      </transition>\n      <transition event=\"dismiss\" target=\"dismissed\">\n        <send type=\"page\" event=\"revert\"><content expr=\"({ id })\"/></send>\n        <assign location=\"chosenID\" expr=\"null\"/>\n      </transition>\n      <transition event=\"ask\" cond=\"_event.data.clip\" target=\"transcribing\">\n        <assign location=\"active\" expr=\"(_event.data &amp;&amp; _event.data.audienceIDs) || []\"/>\n        <send type=\"page\" event=\"revert\"><content expr=\"({ id })\"/></send>\n        <assign location=\"chosenID\" expr=\"null\"/>\n        <assign location=\"clip\" expr=\"_event.data.clip\"/>\n      </transition>\n      <transition event=\"ask\" target=\"asking\">\n        <assign location=\"active\" expr=\"(_event.data &amp;&amp; _event.data.audienceIDs) || []\"/>\n        <send type=\"page\" event=\"revert\"><content expr=\"({ id })\"/></send>\n        <assign location=\"chosenID\" expr=\"null\"/>\n        <assign location=\"messages\" expr=\"messages.concat([{ role: 'user', text: _event.data.text, at: new Date().toISOString() }])\"/>\n        <assign location=\"request\" expr=\"requestOf(false, active, finding)\"/>\n      </transition>\n      <transition event=\"suggest\" target=\"asking\">\n        <assign location=\"active\" expr=\"(_event.data &amp;&amp; _event.data.audienceIDs) || []\"/>\n        <send type=\"page\" event=\"revert\"><content expr=\"({ id })\"/></send>\n        <assign location=\"chosenID\" expr=\"null\"/>\n        <assign location=\"request\" expr=\"requestOf(true, active, finding)\"/>\n      </transition>\n    </state>\n\n    <!-- Approved: the page shows it whenever it is opened, and the export carries it. -->\n    <state id=\"kept\">\n      <onentry><assign location=\"state\" expr=\"'kept'\"/><raise event=\"changed\"/></onentry>\n      <transition event=\"undo\" target=\"suggested\">\n        <send type=\"page\" event=\"revert\"><content expr=\"({ id })\"/></send>\n        <assign location=\"chosenID\" expr=\"null\"/>\n      </transition>\n    </state>\n  </state>\n\n  <final id=\"deleted\">\n    <onentry>\n      <send type=\"page\" event=\"revert\"><content expr=\"({ id })\"/></send>\n      <send type=\"store\" event=\"delete\"><content expr=\"({ id, page })\"/></send>\n      <send type=\"ui\" event=\"removed\"><content expr=\"({ id, page })\"/></send>\n    </onentry>\n  </final>\n</scxml>\n",
  "audiences.scxml": "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!--\n  The audiences of one page: which of the saved audiences read it. The core\n  spawns one actor of this chart for the page it opens, from the page's\n  stored record, and ends it when the panel leaves the page. Its set\n  (`audienceIDs`) is the page's active audiences; until it has one, the\n  page writes for the last set used on any page (the settings'\n  `audienceIDs`).\n\n  A page that links its audiences (`<link rel=\"audience\">`, read by the\n  core into the store as site audiences) is spawned with them as `linked`,\n  in its order: they are its set (`from: 'site'`) unless the reviewer\n  changed it (`from: 'user'`), and such a page is never asked. Opened\n  again with other links, a set from the site follows them.\n\n  A page with no links and no set is asked about once, when it is first opened with a\n  key and saved audiences (`canSuggest`, or `key` later): a cheap request\n  over the page and the audiences' names and descriptions (\"which of\n  these read this page?\"). Its answer is a suggestion the reviewer\n  accepts, adjusts or dismisses; it is never applied by itself.\n\n    unset ──(canSuggest) or key──▶ suggesting ──model.audiences──▶ suggested\n      ▲                               │ none, model.error             │ accept: the suggestion\n      └───────────────────────────────┘                               │ dismiss {audienceIDs}: the set in use\n                                                                      ▼\n    unset, suggesting, suggested ──set {audienceIDs}──────────────▶  set ──set──▶ set\n    restore ──linked, and no set of the reviewer's──────────────────▶ set  (from: 'site')\n\n  `suggestion` is null (never asked), {state: 'asking'}, {state: 'ready',\n  audienceIDs}, {state: 'none'} (the model named none) or {state:\n  'failed', error}; asked once, it is not asked again. Entering `set`\n  clears it. `from` says who chose the set: 'site' (the page's links),\n  'user' (the reviewer, the model's use_audiences, an accepted or\n  dismissed suggestion), null before either. `kind` is the page's kind\n  as it declared it when opened, in its record for the export.\n\n    model  suggest  {url}          → model.audiences {audienceIDs} | model.error {message}\n                                     (sent to this actor by name when the answer comes,\n                                     so opening the page does not wait for it)\n    store  page     its record, after every change\n    ui     page     its record, after every change\n\n  `state` names where it was for the store; an actor spawned with a stored\n  record starts from it (one stored while asking was cut off asks again).\n-->\n<scxml xmlns=\"http://www.w3.org/2005/07/scxml\" version=\"1.0\"\n       datamodel=\"ecmascript\" name=\"audiences\" initial=\"live\">\n  <datamodel>\n    <data id=\"url\"/>\n    <!-- the page's set, in order; null: none yet -->\n    <data id=\"audienceIDs\" expr=\"null\"/>\n    <data id=\"suggestion\" expr=\"null\"/>\n    <data id=\"state\" expr=\"'new'\"/>\n    <!-- spawn only: a key and saved audiences, so a suggestion can be asked for now -->\n    <data id=\"canSuggest\" expr=\"false\"/>\n    <!-- spawn only: the ids of the site audiences the page links, in order; null: it links none -->\n    <data id=\"linked\" expr=\"null\"/>\n    <!-- spawn only: the page's kind (its meta page-kind), kept for the export; null: it declares none -->\n    <data id=\"kind\" expr=\"null\"/>\n    <!-- who chose the set: 'site' | 'user' | null -->\n    <data id=\"from\" expr=\"null\"/>\n  </datamodel>\n\n  <state id=\"live\" initial=\"restore\">\n    <transition event=\"changed\">\n      <send type=\"ui\" event=\"page\" namelist=\"url audienceIDs suggestion state from kind\"/>\n      <send type=\"store\" event=\"page\" namelist=\"url audienceIDs suggestion state from kind\"/>\n    </transition>\n    <!-- the reviewer (or the model's use_audiences) chose the page's set -->\n    <transition event=\"set\" target=\"set\">\n      <assign location=\"audienceIDs\" expr=\"_event.data.audienceIDs\"/>\n      <assign location=\"from\" expr=\"'user'\"/>\n    </transition>\n\n    <state id=\"restore\">\n      <!-- the page's links are its set, unless the reviewer chose one -->\n      <transition cond=\"linked &amp;&amp; linked.length &amp;&amp; (audienceIDs === null || from === 'site')\" target=\"set\">\n        <assign location=\"audienceIDs\" expr=\"linked\"/>\n        <assign location=\"from\" expr=\"'site'\"/>\n      </transition>\n      <transition cond=\"audienceIDs !== null\" target=\"set\"/>\n      <transition cond=\"suggestion &amp;&amp; suggestion.state === 'ready'\" target=\"suggested\"/>\n      <transition cond=\"canSuggest &amp;&amp; (!suggestion || suggestion.state === 'asking')\" target=\"suggesting\"/>\n      <transition target=\"unset\">\n        <if cond=\"suggestion &amp;&amp; suggestion.state === 'asking'\"><assign location=\"suggestion\" expr=\"null\"/></if>\n      </transition>\n    </state>\n\n    <!-- No set: the page writes for the last set used. -->\n    <state id=\"unset\">\n      <onentry>\n        <if cond=\"state !== 'unset'\"><assign location=\"state\" expr=\"'unset'\"/><raise event=\"changed\"/></if>\n      </onentry>\n      <transition event=\"key\" cond=\"!suggestion\" target=\"suggesting\"/>\n    </state>\n\n    <!-- The model is asked which audiences read the page. -->\n    <state id=\"suggesting\">\n      <onentry>\n        <assign location=\"state\" expr=\"'suggesting'\"/>\n        <assign location=\"suggestion\" expr=\"({ state: 'asking' })\"/>\n        <raise event=\"changed\"/>\n        <send type=\"model\" event=\"suggest\" namelist=\"url\"/>\n      </onentry>\n      <transition event=\"model.audiences\" cond=\"(_event.data.audienceIDs || []).length\" target=\"suggested\">\n        <assign location=\"suggestion\" expr=\"({ state: 'ready', audienceIDs: _event.data.audienceIDs })\"/>\n      </transition>\n      <transition event=\"model.audiences\" target=\"unset\">\n        <assign location=\"suggestion\" expr=\"({ state: 'none' })\"/>\n      </transition>\n      <transition event=\"model.error\" target=\"unset\">\n        <assign location=\"suggestion\" expr=\"({ state: 'failed', error: _event.data.message })\"/>\n      </transition>\n      <transition event=\"error.communication\" target=\"unset\">\n        <assign location=\"suggestion\" expr=\"({ state: 'failed', error: 'The model could not be reached.' })\"/>\n      </transition>\n    </state>\n\n    <!-- A suggestion waits for the reviewer. -->\n    <state id=\"suggested\">\n      <onentry><assign location=\"state\" expr=\"'suggested'\"/><raise event=\"changed\"/></onentry>\n      <transition event=\"accept\" target=\"set\">\n        <assign location=\"audienceIDs\" expr=\"suggestion.audienceIDs\"/>\n        <assign location=\"from\" expr=\"'user'\"/>\n      </transition>\n      <!-- not these: the page keeps the set in use -->\n      <transition event=\"dismiss\" target=\"set\">\n        <assign location=\"audienceIDs\" expr=\"_event.data.audienceIDs\"/>\n        <assign location=\"from\" expr=\"'user'\"/>\n      </transition>\n    </state>\n\n    <!-- The page has its own set. -->\n    <state id=\"set\">\n      <onentry>\n        <assign location=\"state\" expr=\"'set'\"/>\n        <assign location=\"suggestion\" expr=\"null\"/>\n        <raise event=\"changed\"/>\n      </onentry>\n      <!-- an answer that comes after the reviewer chose: dropped -->\n      <transition event=\"model.audiences model.error error.communication key\"/>\n    </state>\n  </state>\n</scxml>\n",
  "conversation.scxml": "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!--\n  One conversation of the page chat. A page has any number of them; the\n  core keeps their list and runs the one that is open as an actor of this\n  chart (named `conversation <page> <id>`), so a new conversation starts\n  from nothing and the model reads only this one.\n\n  A conversation is held with the editor (`audienceID` null: the model\n  helps the reviewer improve the copy) or with an audience (`audienceID`\n  names it: the model speaks in the first person as that reader, from what\n  the page says, so the reviewer can check and sharpen the audience). The\n  mode is set when the conversation starts and decides the model request\n  and its tools:\n\n    idle ──chat──▶ asking ─┬─ mode: no audience ─▶ editor ──model.reply──▶ idle\n      ▲                     │                     (`chat`: propose_rewrite, set_note,\n      │                     │                      define_audience, use_audiences,\n      │                     │                      read_as, talk_to)\n      │                     └─ mode: an audience ─▶ reader ──model.reply──▶ idle\n      │                                           (`talk`: update_audience, note_gap)\n      └── chat with a clip ──▶ transcribing ──model.transcript──▶ asking\n\n  The editor: when the model proposes a rewrite of a piece of the page\n  (`propose_rewrite` with `original_text`, and the anchor the model\n  processor found for it), this actor spawns an annotation actor for it,\n  and the model's message names the annotations it made (`annotations`;\n  `proposed` when the model said nothing but the proposals). The audience\n  calls of a reply (`define_audience`, `use_audiences`) go to the\n  `settings` processor, and the model's message names them (`audiences`).\n  `talk_to` (a reply's `talks`, each {audience, audienceID, id}) spawns a\n  new conversation with that audience through the Spawner, opened by this\n  one (`from`: this conversation's id); the core opens it when it first\n  reports, and ends this one.\n\n  The reader: it cannot propose rewrites. `update_audience` (a reply's\n  `audiences` of action 'update', {id, name, changes, fields}) goes to the\n  `settings` processor, which saves the audience, so later readings and\n  conversations use it; the message names it with its changes.\n  `note_gap` (a reply's `gaps`, each {item, explanation}) spawns a\n  page-level open item of kind 'missing', the audience's finding, as a\n  reading's gap does; the message names those annotations.\n\n  A spoken message (`chat` with a clip) is transcribed first, and the\n  transcript is the user's message.\n\n  Reading the page as an audience: the core's `read {readings}` (the\n  reviewer's \"Read as\") and a reply's `readings` (the model's `read_as`)\n  each name the readings to start, {name, audienceID, audience, previous,\n  replaces}; this actor spawns a reading actor (charts/reading.scxml) for\n  each through the Spawner, and they run side by side. The model's message\n  names them as audience chips of action 'read'.\n\n    model    chat         {page, messages}   (the editor)\n                          → model.reply {text, proposed?, rewrites, audiences, readings?, talks?, for, sources?, thoughts?, seconds?}\n                          | model.error {message}\n             talk         {page, audienceID, messages}   (the reader)\n                          → model.reply {text, audiences, gaps, for, thoughts?, seconds?} | model.error {message}\n             transcribe   → model.transcript {text} | model.error {message}   (the clip's id)\n    spawn    spawn        → spawned {name, address}    (tinyactors' Spawner): annotations, readings, conversations\n    settings audience     → audience.saved {ids: {name: id}} | audience.refused {message}\n    store    chat         {page, id, audienceID, messages}, after every change\n    ui       chat         {page, id, audienceID, from, messages, busy, error}, after every change\n-->\n<scxml xmlns=\"http://www.w3.org/2005/07/scxml\" version=\"1.0\"\n       datamodel=\"ecmascript\" name=\"conversation\" initial=\"live\">\n  <datamodel>\n    <data id=\"page\"/>\n    <!-- the conversation's id among the page's -->\n    <data id=\"id\"/>\n    <!-- the audience this conversation is held with; null: the editor -->\n    <data id=\"audienceID\" expr=\"null\"/>\n    <!-- the conversation whose talk_to opened this one, until the core opens it -->\n    <data id=\"from\" expr=\"null\"/>\n    <data id=\"lang\" expr=\"'en'\"/>\n    <data id=\"messages\" expr=\"[]\"/>\n    <data id=\"busy\" expr=\"false\"/>\n    <!-- the id of the clip being transcribed (the core keeps the audio) -->\n    <data id=\"clip\" expr=\"null\"/>\n    <data id=\"spawned\" expr=\"0\"/>\n    <!-- the last request's failure, until the next message -->\n    <data id=\"error\" expr=\"null\"/>\n    <!-- the Spawner's requests of the reply being handled -->\n    <data id=\"pending\" expr=\"[]\"/>\n  </datamodel>\n\n  <script>\n    // The Spawner's request for the annotation actor a rewrite becomes.\n    // A helper of the chart: it reads nothing but its arguments.\n    function annotation(rewrite, page, lang, n) {\n      var id = 'm' + Date.now().toString(36) + '-' + n;\n      return {\n        chart: 'annotation',\n        name: id,\n        params: {\n          id: id, page: page, lang: lang, source: 'model', state: 'new',\n          original: rewrite.original_text,\n          anchor: rewrite.anchor || { quote: { exact: rewrite.original_text, prefix: '', suffix: '' }, selector: '' },\n          suggestions: [{ id: 's1', text: rewrite.replacement, rationale: rewrite.rationale || '', after: 0 }],\n          audiences: rewrite.for || [],\n        },\n      };\n    }\n\n    // The Spawner's request for the open item a reader's note_gap becomes:\n    // a page-level annotation of kind 'missing', the audience's finding.\n    function gap(g, page, lang, audienceID, who, n) {\n      var id = 'g' + Date.now().toString(36) + '-' + n;\n      return {\n        chart: 'annotation',\n        name: id,\n        params: {\n          id: id, page: page, lang: lang, source: 'audience', state: 'new',\n          original: g.item, anchor: null, suggestions: [], audiences: who || [],\n          finding: { audienceID: audienceID, kind: 'missing', explanation: g.explanation || '' },\n        },\n      };\n    }\n\n    // The Spawner's request for the conversation with an audience that a\n    // talk_to of this one opens.\n    function talk(t, page, lang, from) {\n      return {\n        chart: 'conversation',\n        name: 'conversation ' + page + ' ' + t.id,\n        params: { page: page, id: t.id, lang: lang, audienceID: t.audienceID, from: from, messages: [] },\n      };\n    }\n\n    // The model's message of a reply: its words, the annotations its\n    // rewrites or gaps made, the audience calls (an update with its\n    // changes), the conversations it opened, the web pages it was grounded\n    // on and the summary of its thinking.\n    function reply(data, pending) {\n      var m = { role: 'model', text: data.text || 'No change proposed.', at: new Date().toISOString() };\n      if (pending.length) m.annotations = pending.map((p) => p.name);\n      if (data.proposed) m.proposed = true;\n      var named = (data.audiences || []).flatMap((c) => (c.action === 'update'\n        ? [{ name: c.name, action: 'update', id: c.id, changes: c.changes || [] }]\n        : (c.action === 'use' ? c.names : [c.name]).map((name) => ({ name: name, action: c.action }))));\n      named = named.concat((data.readings || []).map((r) => ({ name: r.audience, action: 'read', id: r.audienceID })));\n      named = named.concat((data.talks || []).map((t) => ({ name: t.audience, action: 'talk', id: t.audienceID, chat: t.id })));\n      if (named.length) m.audiences = named;\n      if (data.sources &amp;&amp; data.sources.length) m.sources = data.sources;\n      if (data.thoughts) m.thoughts = data.thoughts;\n      if (data.seconds) m.seconds = data.seconds;\n      return m;\n    }\n\n    // The Spawner's request for a reading actor of one audience.\n    function reading(r, page, lang) {\n      return {\n        chart: 'reading', name: r.name,\n        params: {\n          name: r.name, page: page, lang: lang, audienceID: r.audienceID, audience: r.audience,\n          previous: r.previous || [], replaces: r.replaces || null, state: 'new',\n        },\n      };\n    }\n  </script>\n\n  <state id=\"live\" initial=\"idle\">\n    <!-- Every state raises `changed`: the conversation goes to the panel and to the store. -->\n    <transition event=\"changed\">\n      <send type=\"ui\" event=\"chat\" namelist=\"page id audienceID from messages busy error\"/>\n      <send type=\"store\" event=\"chat\" namelist=\"page id audienceID messages\"/>\n    </transition>\n    <!-- the settings processor's answers: a saved audience's id on its chip; a refusal is the error -->\n    <transition event=\"audience.saved\">\n      <assign location=\"messages\" expr=\"messages.map((m) => m.audiences ? Object.assign({}, m, { audiences: m.audiences.map((a) => (!a.id &amp;&amp; _event.data.ids[a.name] ? Object.assign({}, a, { id: _event.data.ids[a.name] }) : a)) }) : m)\"/>\n      <raise event=\"changed\"/>\n    </transition>\n    <transition event=\"audience.refused\">\n      <assign location=\"error\" expr=\"_event.data.message\"/>\n      <raise event=\"changed\"/>\n    </transition>\n    <!-- the reviewer's \"Read as\": a reading actor per audience, whatever this conversation is doing -->\n    <transition event=\"read\">\n      <foreach array=\"_event.data.readings\" item=\"r\">\n        <send type=\"spawn\" event=\"spawn\"><content expr=\"reading(r, page, lang)\"/></send>\n      </foreach>\n    </transition>\n    <transition event=\"spawned\"/>\n\n    <state id=\"idle\">\n      <onentry><assign location=\"busy\" expr=\"false\"/><raise event=\"changed\"/></onentry>\n      <transition event=\"chat\" cond=\"_event.data.clip\" target=\"transcribing\">\n        <assign location=\"error\" expr=\"null\"/>\n        <assign location=\"clip\" expr=\"_event.data.clip\"/>\n      </transition>\n      <transition event=\"chat\" target=\"asking\">\n        <assign location=\"error\" expr=\"null\"/>\n        <assign location=\"messages\" expr=\"messages.concat([{ role: 'user', text: _event.data.text, at: new Date().toISOString() }])\"/>\n      </transition>\n    </state>\n\n    <!-- A spoken message: the model writes down what was said, and that is the message. -->\n    <state id=\"transcribing\">\n      <onentry>\n        <assign location=\"busy\" expr=\"true\"/>\n        <raise event=\"changed\"/>\n        <send type=\"model\" event=\"transcribe\" namelist=\"page clip\"/>\n      </onentry>\n      <onexit><assign location=\"clip\" expr=\"null\"/></onexit>\n      <transition event=\"model.transcript\" cond=\"String(_event.data.text || '').trim()\" target=\"asking\">\n        <assign location=\"messages\" expr=\"messages.concat([{ role: 'user', text: String(_event.data.text).trim(), at: new Date().toISOString(), spoken: true }])\"/>\n      </transition>\n      <transition event=\"model.transcript\" target=\"idle\">\n        <assign location=\"error\" expr=\"'Nothing was heard.'\"/>\n      </transition>\n      <transition event=\"model.error\" target=\"idle\">\n        <assign location=\"error\" expr=\"_event.data.message\"/>\n      </transition>\n      <transition event=\"error.communication\" target=\"idle\">\n        <assign location=\"error\" expr=\"'The model could not be reached.'\"/>\n      </transition>\n    </state>\n\n    <state id=\"asking\" initial=\"mode\">\n      <onentry>\n        <assign location=\"busy\" expr=\"true\"/>\n        <raise event=\"changed\"/>\n      </onentry>\n      <transition event=\"model.error\" target=\"idle\">\n        <assign location=\"error\" expr=\"_event.data.message\"/>\n      </transition>\n      <transition event=\"error.communication\" target=\"idle\">\n        <assign location=\"error\" expr=\"'The model could not be reached.'\"/>\n      </transition>\n\n      <!-- The conversation's mode decides the request: the editor's or the reader's. -->\n      <state id=\"mode\">\n        <transition cond=\"audienceID\" target=\"reader\"/>\n        <transition target=\"editor\"/>\n      </state>\n\n      <!-- The editor: rewrites become annotations, audience calls go to settings, talk_to opens a conversation. -->\n      <state id=\"editor\">\n        <onentry><send type=\"model\" event=\"chat\" namelist=\"page messages\"/></onentry>\n        <transition event=\"model.reply\" target=\"idle\">\n          <assign location=\"pending\" expr=\"(_event.data.rewrites || []).filter((r) => r.original_text).map((r, i) => annotation(r, page, lang, spawned + i + 1))\"/>\n          <assign location=\"spawned\" expr=\"spawned + pending.length\"/>\n          <assign location=\"messages\" expr=\"messages.concat([reply(_event.data, pending)])\"/>\n          <foreach array=\"pending\" item=\"spawn\">\n            <send type=\"spawn\" event=\"spawn\"><content expr=\"spawn\"/></send>\n          </foreach>\n          <foreach array=\"_event.data.audiences || []\" item=\"call\">\n            <send type=\"settings\" event=\"audience\"><content expr=\"call\"/></send>\n          </foreach>\n          <foreach array=\"_event.data.readings || []\" item=\"r\">\n            <send type=\"spawn\" event=\"spawn\"><content expr=\"reading(r, page, lang)\"/></send>\n          </foreach>\n          <foreach array=\"_event.data.talks || []\" item=\"t\">\n            <send type=\"spawn\" event=\"spawn\"><content expr=\"talk(t, page, lang, id)\"/></send>\n          </foreach>\n          <assign location=\"pending\" expr=\"[]\"/>\n        </transition>\n      </state>\n\n      <!-- The reader: speaks as the audience; its corrections refine the audience, its gaps become open items. -->\n      <state id=\"reader\">\n        <onentry><send type=\"model\" event=\"talk\" namelist=\"page audienceID messages\"/></onentry>\n        <transition event=\"model.reply\" target=\"idle\">\n          <assign location=\"pending\" expr=\"(_event.data.gaps || []).map((g, i) => gap(g, page, lang, audienceID, _event.data.for, spawned + i + 1))\"/>\n          <assign location=\"spawned\" expr=\"spawned + pending.length\"/>\n          <assign location=\"messages\" expr=\"messages.concat([reply(_event.data, pending)])\"/>\n          <foreach array=\"pending\" item=\"spawn\">\n            <send type=\"spawn\" event=\"spawn\"><content expr=\"spawn\"/></send>\n          </foreach>\n          <foreach array=\"_event.data.audiences || []\" item=\"call\">\n            <send type=\"settings\" event=\"audience\"><content expr=\"call\"/></send>\n          </foreach>\n          <assign location=\"pending\" expr=\"[]\"/>\n        </transition>\n      </state>\n    </state>\n  </state>\n</scxml>\n",
  "plan.scxml": "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!--\n  The revision plan of one page (\"Revise page\"): one model request over\n  everything the reviewer gathered (the page's kind and audiences, its\n  sections' claims, every reading's checklist, the open findings, the kept\n  changes and open notes, the voice, and the site map: the other pages with\n  their kind and audiences) that decides WHERE each need is answered, then\n  the reviewer's decision on each item.\n\n  The core spawns one actor of this chart for the page it opens, from the\n  page's stored plan (or none), and ends it when the panel leaves the page.\n\n    idle ──plan──▶ planning ──model.plan──▶ planned ──plan──▶ planning\n                     │                        │ accept {id} | reject {id} | acceptAll\n                     │ model.error            ▼\n                     ▼                      planned (each item decided)\n                   failed ──plan──▶ planning\n\n  Re-planning replaces the items the reviewer has not decided and keeps\n  the decided ones (accepted or rejected); a new item that repeats a\n  decided one (same action, target, text on the page and needs) is\n  dropped, as a new page of a decided one's title is. The model is told\n  the decided items, so it neither repeats nor undoes them.\n\n  The core has already routed each item when it comes (src/core/plan.mjs,\n  `planOf`): a rewrite or add here of a need whose kind is not the page's\n  became a `link` here (one short line and a link) to the page of that\n  kind and audience, or to a new page. Accepting an item:\n\n    rewrite, cut   an annotation here (source 'plan'; its suggestion the\n                   plan's text, '' for a cut), previewed and kept as usual\n    add            a page-level open item here, the drafted copy its suggestion\n    link           an annotation here (anchored: the sentence becomes the\n                   line; else a page-level item), and a task for the target\n    move           a task for the target (no annotation here)\n    new page       a proposed page, exported with its kind, audiences and outline\n\n  An annotation made of an item carries `plan` {itemID, action, needs,\n  criteria, target, where}; the export lists the criteria of accepted\n  items under the page they name (\"Acceptance criteria\", \"Other pages\").\n\n    model  plan    {page}\n                   → model.plan {items, newPages, sitePages, thoughts?, seconds?} | model.error {message}\n    spawn  spawn   an annotation per accepted rewrite, cut, add and link → spawned {name, address}\n    store  plan    its record, after every change\n    ui     plan    its record, after every change\n\n  An item: {id, action: 'rewrite' | 'add' | 'cut' | 'link' | 'move',\n  needs: [needID], target: 'here' | URL | 'new', original_text?, anchor?,\n  text, target_text?, where?, reason, criteria: [{needID, text, page}],\n  conflict?, routed?, audiences: [name], decision: null | 'accepted' |\n  'rejected', annotationID?}. A new page: {id, title, kind, audiences,\n  outline: [line], needs, criteria, reason?, decision}.\n\n  `state` names where it was for the store; an actor spawned with a\n  stored record starts from it (one stored while planning was cut off:\n  failed).\n-->\n<scxml xmlns=\"http://www.w3.org/2005/07/scxml\" version=\"1.0\"\n       datamodel=\"ecmascript\" name=\"plan\" initial=\"live\">\n  <datamodel>\n    <data id=\"page\"/>\n    <data id=\"lang\" expr=\"'en'\"/>\n    <data id=\"state\" expr=\"'new'\"/>\n    <data id=\"started\" expr=\"null\"/>\n    <!-- when the plan was answered -->\n    <data id=\"at\" expr=\"null\"/>\n    <data id=\"items\" expr=\"[]\"/>\n    <data id=\"newPages\" expr=\"[]\"/>\n    <!-- how many pages of the site map the plan was made with -->\n    <data id=\"sitePages\" expr=\"0\"/>\n    <data id=\"error\" expr=\"null\"/>\n    <data id=\"thoughts\" expr=\"null\"/>\n    <data id=\"seconds\" expr=\"null\"/>\n    <!-- the Spawner's requests of the decision being handled -->\n    <data id=\"pending\" expr=\"[]\"/>\n  </datamodel>\n\n  <script>\n    // Two items are the same proposal: one action, target, text on the page and needs.\n    function same(a, b) {\n      return a.action === b.action &amp;&amp; a.target === b.target\n        &amp;&amp; String(a.original_text || '') === String(b.original_text || '')\n        &amp;&amp; (a.needs || []).join(' ') === (b.needs || []).join(' ');\n    }\n\n    // A new plan's items: the decided ones of the last, then the new ones\n    // that repeat none of them.\n    function merge(before, fresh) {\n      var kept = before.filter(function (x) { return x.decision; });\n      return kept.concat(fresh.filter(function (f) { return !kept.some(function (k) { return same(k, f); }); }));\n    }\n    function mergePages(before, fresh) {\n      var kept = before.filter(function (x) { return x.decision; });\n      var title = function (p) { return String(p.title || '').trim().toLowerCase(); };\n      return kept.concat(fresh.filter(function (f) { return !kept.some(function (k) { return title(k) === title(f); }); }));\n    }\n\n    // The Spawner's request for the annotation an accepted item becomes\n    // here, or null (a move, a rewrite elsewhere: a task only).\n    function annotationOf(x, r) {\n      if (x.target !== 'here' &amp;&amp; x.action !== 'link') return null;\n      var placed = Boolean(x.anchor);\n      if (x.action === 'cut' &amp;&amp; !placed) return null;\n      var id = x.id + '-a';\n      return {\n        chart: 'annotation', name: id,\n        params: {\n          id: id, page: r.page, lang: r.lang, source: 'plan', state: 'new',\n          original: placed ? x.anchor.quote.exact : (x.reason || x.text),\n          anchor: x.anchor || null,\n          suggestions: [{ id: 's1', text: x.action === 'cut' ? '' : x.text, rationale: x.reason || '', after: 0 }],\n          audiences: x.audiences || [],\n          plan: { itemID: x.id, action: x.action, needs: x.needs || [], criteria: x.criteria || [], target: x.target, where: x.where || null },\n        },\n      };\n    }\n\n    // `ids` decided as `decision`: each item and new page named, not decided yet.\n    function decide(list, ids, decision) {\n      return list.map(function (x) {\n        if (x.decision || ids.indexOf(x.id) &lt; 0) return x;\n        var y = Object.assign({}, x, { decision: decision });\n        if (decision === 'accepted' &amp;&amp; annotationOf(x, { page: '', lang: '' })) y.annotationID = x.id + '-a';\n        return y;\n      });\n    }\n    function undecided(list) {\n      return list.filter(function (x) { return !x.decision; }).map(function (x) { return x.id; });\n    }\n  </script>\n\n  <state id=\"live\" initial=\"restore\">\n    <!-- Every state raises `changed`: the record goes to the panel and to the store. -->\n    <transition event=\"changed\">\n      <send type=\"ui\" event=\"plan\" namelist=\"page lang state started at items newPages sitePages error thoughts seconds\"/>\n      <send type=\"store\" event=\"plan\" namelist=\"page lang state started at items newPages sitePages error thoughts seconds\"/>\n    </transition>\n    <!-- a spawn's answer, or a spawn whose actor is gone: nothing to do -->\n    <transition event=\"spawned error.communication\"/>\n\n    <!-- The reviewer decides an item or a new page, whatever the plan's state:\n         a re-plan keeps the decided ones. -->\n    <transition event=\"accept\">\n      <assign location=\"pending\" expr=\"items.filter((x) => x.id === _event.data.id &amp;&amp; !x.decision).map((x) => annotationOf(x, { page, lang })).filter(Boolean)\"/>\n      <foreach array=\"pending\" item=\"spawn\">\n        <send type=\"spawn\" event=\"spawn\"><content expr=\"spawn\"/></send>\n      </foreach>\n      <assign location=\"items\" expr=\"decide(items, [_event.data.id], 'accepted')\"/>\n      <assign location=\"newPages\" expr=\"decide(newPages, [_event.data.id], 'accepted')\"/>\n      <assign location=\"pending\" expr=\"[]\"/>\n      <raise event=\"changed\"/>\n    </transition>\n    <transition event=\"acceptAll\">\n      <assign location=\"pending\" expr=\"items.filter((x) => !x.decision).map((x) => annotationOf(x, { page, lang })).filter(Boolean)\"/>\n      <foreach array=\"pending\" item=\"spawn\">\n        <send type=\"spawn\" event=\"spawn\"><content expr=\"spawn\"/></send>\n      </foreach>\n      <assign location=\"items\" expr=\"decide(items, undecided(items), 'accepted')\"/>\n      <assign location=\"newPages\" expr=\"decide(newPages, undecided(newPages), 'accepted')\"/>\n      <assign location=\"pending\" expr=\"[]\"/>\n      <raise event=\"changed\"/>\n    </transition>\n    <transition event=\"reject\">\n      <assign location=\"items\" expr=\"decide(items, [_event.data.id], 'rejected')\"/>\n      <assign location=\"newPages\" expr=\"decide(newPages, [_event.data.id], 'rejected')\"/>\n      <raise event=\"changed\"/>\n    </transition>\n\n    <!-- A new actor, or one the store gave back: go to the state it was in. -->\n    <state id=\"restore\">\n      <transition cond=\"state === 'planned'\" target=\"planned\"/>\n      <transition cond=\"state === 'failed'\" target=\"failed\"/>\n      <transition cond=\"state === 'planning'\" target=\"failed\">\n        <assign location=\"error\" expr=\"'The plan was cut off: plan again.'\"/>\n      </transition>\n      <transition target=\"idle\"/>\n    </state>\n\n    <!-- No plan yet. -->\n    <state id=\"idle\">\n      <onentry><assign location=\"state\" expr=\"'idle'\"/></onentry>\n      <transition event=\"plan\" target=\"planning\"/>\n    </state>\n\n    <!-- The model plans the page; the last plan's items stay shown meanwhile. -->\n    <state id=\"planning\">\n      <onentry>\n        <assign location=\"state\" expr=\"'planning'\"/>\n        <assign location=\"started\" expr=\"new Date().toISOString()\"/>\n        <assign location=\"error\" expr=\"null\"/>\n        <raise event=\"changed\"/>\n        <send type=\"model\" event=\"plan\" namelist=\"page\"/>\n      </onentry>\n      <!-- one plan at a time -->\n      <transition event=\"plan\"/>\n      <transition event=\"model.plan\" target=\"planned\">\n        <assign location=\"items\" expr=\"merge(items, _event.data.items || [])\"/>\n        <assign location=\"newPages\" expr=\"mergePages(newPages, _event.data.newPages || [])\"/>\n        <assign location=\"sitePages\" expr=\"_event.data.sitePages || 0\"/>\n        <assign location=\"at\" expr=\"new Date().toISOString()\"/>\n        <assign location=\"thoughts\" expr=\"_event.data.thoughts || null\"/>\n        <assign location=\"seconds\" expr=\"_event.data.seconds || null\"/>\n      </transition>\n      <transition event=\"model.error\" target=\"failed\">\n        <assign location=\"error\" expr=\"_event.data.message\"/>\n      </transition>\n      <transition event=\"error.communication\" target=\"failed\">\n        <assign location=\"error\" expr=\"'The model could not be reached.'\"/>\n      </transition>\n    </state>\n\n    <!-- Planned: each item waits for the reviewer's decision. -->\n    <state id=\"planned\">\n      <onentry><assign location=\"state\" expr=\"'planned'\"/><raise event=\"changed\"/></onentry>\n      <transition event=\"plan\" target=\"planning\"/>\n    </state>\n\n    <!-- The request failed: the last plan's items stay until a new one answers. -->\n    <state id=\"failed\">\n      <onentry><assign location=\"state\" expr=\"'failed'\"/><raise event=\"changed\"/></onentry>\n      <transition event=\"plan\" target=\"planning\"/>\n    </state>\n  </state>\n</scxml>\n",
  "reading.scxml": "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!--\n  One reading of a page as one audience: the model reads the whole page as\n  that reader and says where they get stuck (findings) and which of their\n  wants, tasks and objections the page answers (the checklist).\n\n  The page chat's conversation actor spawns one reading actor per audience\n  through the Spawner, when the reviewer asks (\"Read as\", the `read`\n  command) or the model does (`read_as`); several run side by side. An\n  actor of this chart:\n\n    reading ──model.reading──▶ done      the checklist is `items`; each finding\n       │                         │       becomes an annotation actor (spawned\n       │ model.error             │ gap   through the Spawner), named in `findingIDs`\n       ▼                         ▼\n    failed ──retry──▶ reading   done     a checklist gap made an open item\n\n  Reading an audience again starts a new actor, given the last reading's\n  findings (`previous`) and actor (`replaces`). When its answer comes it\n  tells each previous finding to `retire` (an annotation the reviewer has\n  not touched deletes itself; one kept, dismissed, edited, noted or asked\n  about stays) and the previous reading that it is `superseded` (it ends).\n  Both go by name, to the actors' local addresses.\n\n    model    read        {page, audienceID}\n                         → model.reading {items, findings, thoughts?, seconds?} | model.error {message}\n    spawn    spawn       an annotation per finding, and per gap opened → spawned {name, address}\n    (actors) retire      to each previous finding;  superseded  to the previous reading\n    store    reading     its record, after every change\n    ui       reading     its record, after every change\n\n  An item of `items`: {field: 'wants' | 'tasks' | 'objections', text,\n  status: 'answered' | 'partial' | 'missing', anchor?, explanation,\n  annotationID?, needID?, kind?, claimed?}: the anchor of the text that\n  answers it, and the open item made of it; for a site audience's item,\n  its need's reference (`audience.need`), the kind of page it belongs on\n  (pitch, tutorial, how-to, reference, explanation) and the headings of\n  the sections that claim to answer it (`data-answers`). A finding:\n  {kind: 'objection' | 'task' | 'doubt' | 'jargon' | 'missing', anchor?,\n  original_text?, need, explanation, replacement?, section?, needID?};\n  one without an anchor is page-level; needID: the item it is about.\n\n  `state` names where it was for the store; an actor spawned with a stored\n  record starts from it (one stored while reading was cut off: failed).\n-->\n<scxml xmlns=\"http://www.w3.org/2005/07/scxml\" version=\"1.0\"\n       datamodel=\"ecmascript\" name=\"reading\" initial=\"live\">\n  <datamodel>\n    <!-- the actor's own name, and the system's base for the names of others -->\n    <data id=\"name\"/>\n    <data id=\"page\"/>\n    <data id=\"lang\" expr=\"'en'\"/>\n    <data id=\"audienceID\"/>\n    <!-- the audience's name, for the annotations' \"written for\" -->\n    <data id=\"audience\" expr=\"''\"/>\n    <data id=\"state\" expr=\"'new'\"/>\n    <data id=\"started\" expr=\"null\"/>\n    <!-- when the reading was answered -->\n    <data id=\"at\" expr=\"null\"/>\n    <data id=\"items\" expr=\"[]\"/>\n    <data id=\"findingIDs\" expr=\"[]\"/>\n    <!-- the previous reading's findings and actor, until this one replaces them -->\n    <data id=\"previous\" expr=\"[]\"/>\n    <data id=\"replaces\" expr=\"null\"/>\n    <data id=\"error\" expr=\"null\"/>\n    <data id=\"thoughts\" expr=\"null\"/>\n    <data id=\"seconds\" expr=\"null\"/>\n    <!-- the Spawner's requests of the answer being handled -->\n    <data id=\"pending\" expr=\"[]\"/>\n  </datamodel>\n\n  <script>\n    // An actor's local address in this system, by its name.\n    function address(name) {\n      return 'tinyactors://copywriter/@' + encodeURIComponent(name);\n    }\n\n    // The Spawner's request for the annotation a finding becomes: anchored\n    // where the reader gets stuck, or page-level (no anchor) for what the\n    // page lacks. The proposed rewrite is its first suggestion.\n    function finding(f, r, n) {\n      var id = 'f' + Date.now().toString(36) + '-' + n;\n      var placed = Boolean(f.anchor);\n      var params = {\n        id: id, page: r.page, lang: r.lang, source: 'audience', state: 'new',\n        original: placed ? f.anchor.quote.exact : (f.need || f.original_text || f.explanation),\n        anchor: f.anchor || null,\n        suggestions: f.replacement ? [{ id: 's1', text: f.replacement, rationale: f.explanation, after: 0 }] : [],\n        audiences: r.audience ? [r.audience] : [],\n        finding: { audienceID: r.audienceID, kind: f.kind, explanation: f.explanation },\n      };\n      if (f.section) params.finding.section = f.section;\n      if (f.need) params.finding.need = f.need;\n      if (f.needID) params.finding.needID = f.needID;\n      return { chart: 'annotation', name: id, params: params };\n    }\n\n    // The Spawner's request for the open item a checklist gap becomes: a\n    // page-level annotation of kind 'missing'.\n    function gap(item, id, r) {\n      var about = { field: item.field, status: item.status };\n      var found = { audienceID: r.audienceID, kind: 'missing', explanation: item.explanation || '', item: about };\n      if (item.needID) found.needID = item.needID;\n      if (item.needID) about.needID = item.needID;\n      if (item.kind) about.kind = item.kind;\n      return {\n        chart: 'annotation', name: id,\n        params: {\n          id: id, page: r.page, lang: r.lang, source: 'audience', state: 'new',\n          original: item.text, anchor: null, suggestions: [], audiences: r.audience ? [r.audience] : [],\n          finding: found,\n        },\n      };\n    }\n  </script>\n\n  <state id=\"live\" initial=\"restore\">\n    <!-- Every state raises `changed`: the record goes to the panel and to the store. -->\n    <transition event=\"changed\">\n      <send type=\"ui\" event=\"reading\" namelist=\"name page lang audienceID audience state started at items findingIDs previous replaces error thoughts seconds\"/>\n      <send type=\"store\" event=\"reading\" namelist=\"name page lang audienceID audience state started at items findingIDs previous replaces error thoughts seconds\"/>\n    </transition>\n    <!-- a newer reading of the same audience answered: this one ends -->\n    <transition event=\"superseded\" target=\"ended\"/>\n    <!-- a retire or a spawn whose actor is gone: nothing to do -->\n    <transition event=\"error.communication spawned\"/>\n\n    <!-- A new actor, or one the store gave back: go to the state it was in. -->\n    <state id=\"restore\">\n      <transition cond=\"state === 'done'\" target=\"done\"/>\n      <transition cond=\"state === 'failed'\" target=\"failed\"/>\n      <transition cond=\"state === 'reading'\" target=\"failed\">\n        <assign location=\"error\" expr=\"'The reading was cut off: read again.'\"/>\n      </transition>\n      <transition target=\"reading\"/>\n    </state>\n\n    <!-- The model reads the page as the audience. -->\n    <state id=\"reading\">\n      <onentry>\n        <assign location=\"state\" expr=\"'reading'\"/>\n        <assign location=\"started\" expr=\"new Date().toISOString()\"/>\n        <assign location=\"error\" expr=\"null\"/>\n        <raise event=\"changed\"/>\n        <send type=\"model\" event=\"read\" namelist=\"page audienceID\"/>\n      </onentry>\n      <transition event=\"model.reading\" target=\"done\">\n        <assign location=\"items\" expr=\"_event.data.items || []\"/>\n        <assign location=\"pending\" expr=\"(_event.data.findings || []).map((f, i) => finding(f, { page, lang, audienceID, audience }, i + 1))\"/>\n        <assign location=\"findingIDs\" expr=\"pending.map((p) => p.name)\"/>\n        <assign location=\"at\" expr=\"new Date().toISOString()\"/>\n        <assign location=\"thoughts\" expr=\"_event.data.thoughts || null\"/>\n        <assign location=\"seconds\" expr=\"_event.data.seconds || null\"/>\n        <foreach array=\"pending\" item=\"spawn\">\n          <send type=\"spawn\" event=\"spawn\"><content expr=\"spawn\"/></send>\n        </foreach>\n        <!-- the previous reading's findings: the untouched ones delete themselves -->\n        <foreach array=\"previous\" item=\"old\">\n          <send targetexpr=\"address(old)\" event=\"retire\"/>\n        </foreach>\n        <if cond=\"replaces\">\n          <send targetexpr=\"address(replaces)\" event=\"superseded\"/>\n        </if>\n        <assign location=\"previous\" expr=\"[]\"/>\n        <assign location=\"replaces\" expr=\"null\"/>\n        <assign location=\"pending\" expr=\"[]\"/>\n      </transition>\n      <transition event=\"model.error\" target=\"failed\">\n        <assign location=\"error\" expr=\"_event.data.message\"/>\n      </transition>\n      <transition event=\"error.communication\" target=\"failed\">\n        <assign location=\"error\" expr=\"'The model could not be reached.'\"/>\n      </transition>\n    </state>\n\n    <!-- The request failed: the previous reading stays until a retry answers. -->\n    <state id=\"failed\">\n      <onentry><assign location=\"state\" expr=\"'failed'\"/><raise event=\"changed\"/></onentry>\n      <transition event=\"retry\" target=\"reading\"/>\n    </state>\n\n    <!-- Answered: the checklist stays, and a gap of it can become an open item. -->\n    <state id=\"done\">\n      <onentry><assign location=\"state\" expr=\"'done'\"/><raise event=\"changed\"/></onentry>\n      <transition event=\"gap\" cond=\"items[_event.data.index] &amp;&amp; !items[_event.data.index].annotationID &amp;&amp; items[_event.data.index].status !== 'answered'\">\n        <send type=\"spawn\" event=\"spawn\"><content expr=\"gap(items[_event.data.index], _event.data.id, { page, lang, audienceID, audience })\"/></send>\n        <assign location=\"items\" expr=\"items.map((x, i) => (i === _event.data.index ? Object.assign({}, x, { annotationID: _event.data.id }) : x))\"/>\n        <raise event=\"changed\"/>\n      </transition>\n    </state>\n  </state>\n\n  <final id=\"ended\"/>\n</scxml>\n",
};

/** The work packet's schema, copied into every export. */
export const workPacketXSD = "<?xml version='1.0' encoding='UTF-8'?>\n<xs:schema xmlns:xs=\"http://www.w3.org/2001/XMLSchema\">\n  <xs:simpleType name=\"sha\"><xs:restriction base=\"xs:string\"><xs:pattern value=\"[0-9a-f]{64}\"/></xs:restriction></xs:simpleType>\n  <xs:complexType name=\"page\"><xs:attribute name=\"id\" type=\"xs:ID\" use=\"required\"/><xs:attribute name=\"url\" type=\"xs:anyURI\" use=\"required\"/><xs:attribute name=\"fingerprint\" type=\"sha\" use=\"required\"/><xs:attribute name=\"locale\" type=\"xs:language\" use=\"required\"/></xs:complexType>\n  <xs:complexType name=\"anchor\"><xs:attribute name=\"id\" type=\"xs:ID\" use=\"required\"/><xs:attribute name=\"pageRef\" type=\"xs:IDREF\" use=\"required\"/><xs:attribute name=\"selector\" type=\"xs:string\" use=\"required\"/><xs:attribute name=\"domPath\" type=\"xs:string\" use=\"required\"/><xs:attribute name=\"textSha256\" type=\"sha\" use=\"required\"/><xs:attribute name=\"textQuote\" type=\"xs:string\" use=\"required\"/></xs:complexType>\n  <xs:complexType name=\"observation\"><xs:sequence><xs:element name=\"text\" type=\"xs:string\"/></xs:sequence><xs:attribute name=\"id\" type=\"xs:ID\" use=\"required\"/><xs:attribute name=\"authorRef\" type=\"xs:string\" use=\"required\"/><xs:attribute name=\"anchorRef\" type=\"xs:IDREF\" use=\"required\"/><xs:attribute name=\"source\" type=\"xs:string\" use=\"required\"/><xs:attribute name=\"recordedAt\" type=\"xs:dateTime\" use=\"required\"/></xs:complexType>\n  <xs:complexType name=\"revision\"><xs:attribute name=\"id\" type=\"xs:ID\" use=\"required\"/><xs:attribute name=\"patchId\" type=\"xs:string\" use=\"required\"/><xs:attribute name=\"anchorRef\" type=\"xs:IDREF\" use=\"required\"/><xs:attribute name=\"observationRef\" type=\"xs:IDREF\" use=\"required\"/><xs:attribute name=\"accepted\" type=\"xs:string\" use=\"required\" fixed=\"true\"/><xs:attribute name=\"expectedSha256\" type=\"sha\" use=\"required\"/><xs:attribute name=\"replacementSha256\" type=\"sha\" use=\"required\"/></xs:complexType>\n  <xs:complexType name=\"asset\"><xs:attribute name=\"id\" type=\"xs:ID\" use=\"required\"/><xs:attribute name=\"mediaType\" type=\"xs:string\" use=\"required\"/><xs:attribute name=\"sha256\" type=\"sha\" use=\"required\"/><xs:attribute name=\"uri\" type=\"xs:anyURI\" use=\"required\"/><xs:attribute name=\"captureMethod\" type=\"xs:string\" use=\"required\"/><xs:attribute name=\"consent\" type=\"xs:string\" use=\"required\"/></xs:complexType>\n  <xs:complexType name=\"copyChange\"><xs:sequence><xs:element name=\"expected\" type=\"xs:string\"/><xs:element name=\"replacement\" type=\"xs:string\"/><xs:element name=\"rationale\" type=\"xs:string\"/><xs:element name=\"acceptance\" type=\"xs:string\"/></xs:sequence><xs:attribute name=\"id\" type=\"xs:ID\" use=\"required\"/><xs:attribute name=\"observationRef\" type=\"xs:IDREF\" use=\"required\"/><xs:attribute name=\"anchorRef\" type=\"xs:IDREF\" use=\"required\"/><xs:attribute name=\"revisionRef\" type=\"xs:IDREF\" use=\"required\"/><xs:attribute name=\"operation\" use=\"required\" fixed=\"replace_text\" type=\"xs:string\"/><xs:attribute name=\"accepted\" use=\"required\" fixed=\"true\" type=\"xs:string\"/></xs:complexType>\n  <xs:complexType name=\"designTask\"><xs:sequence><xs:element name=\"summary\" type=\"xs:string\"/><xs:element name=\"instructions\" type=\"xs:string\"/><xs:element name=\"acceptance\" type=\"xs:string\"/></xs:sequence><xs:attribute name=\"id\" type=\"xs:ID\" use=\"required\"/><xs:attribute name=\"observationRef\" type=\"xs:IDREF\" use=\"required\"/><xs:attribute name=\"assetRef\" type=\"xs:IDREF\" use=\"optional\"/><xs:attribute name=\"status\" type=\"xs:string\" use=\"required\" fixed=\"open\"/></xs:complexType>\n  <xs:element name=\"work-packet\">\n    <xs:complexType><xs:sequence><xs:element name=\"title\" type=\"xs:string\"/>\n      <xs:element name=\"payload\"><xs:complexType><xs:sequence>\n        <xs:element name=\"sources\"><xs:complexType><xs:sequence>\n          <xs:element name=\"page\" type=\"page\" minOccurs=\"1\" maxOccurs=\"unbounded\"/>\n          <xs:element name=\"anchor\" type=\"anchor\" minOccurs=\"1\" maxOccurs=\"unbounded\"/>\n          <xs:element name=\"observation\" type=\"observation\" minOccurs=\"1\" maxOccurs=\"unbounded\"/>\n          <xs:element name=\"revision\" type=\"revision\" minOccurs=\"0\" maxOccurs=\"unbounded\"/>\n          <xs:element name=\"asset\" type=\"asset\" minOccurs=\"0\" maxOccurs=\"unbounded\"/>\n        </xs:sequence></xs:complexType></xs:element>\n        <xs:element name=\"items\"><xs:complexType><xs:choice minOccurs=\"1\" maxOccurs=\"unbounded\"><xs:element name=\"copy-change\" type=\"copyChange\"/><xs:element name=\"design-task\" type=\"designTask\"/></xs:choice></xs:complexType></xs:element>\n      </xs:sequence></xs:complexType></xs:element>\n      <xs:element name=\"handoff\" minOccurs=\"0\"><xs:complexType><xs:attribute name=\"status\" type=\"xs:string\" use=\"required\"/><xs:attribute name=\"integration\" type=\"xs:string\" use=\"required\"/></xs:complexType></xs:element>\n    </xs:sequence>\n    <xs:attribute name=\"id\" type=\"xs:ID\" use=\"required\"/><xs:attribute name=\"version\" type=\"xs:positiveInteger\" use=\"required\"/><xs:attribute name=\"projectId\" type=\"xs:string\" use=\"required\"/><xs:attribute name=\"sessionId\" type=\"xs:string\" use=\"required\"/><xs:attribute name=\"status\" type=\"xs:string\" use=\"required\"/><xs:attribute name=\"payloadDigest\" type=\"sha\" use=\"required\"/>\n    </xs:complexType>\n    <xs:key name=\"pageKey\"><xs:selector xpath=\"payload/sources/page\"/><xs:field xpath=\"@id\"/></xs:key>\n    <xs:key name=\"anchorKey\"><xs:selector xpath=\"payload/sources/anchor\"/><xs:field xpath=\"@id\"/></xs:key>\n    <xs:key name=\"observationKey\"><xs:selector xpath=\"payload/sources/observation\"/><xs:field xpath=\"@id\"/></xs:key>\n    <xs:key name=\"revisionKey\"><xs:selector xpath=\"payload/sources/revision\"/><xs:field xpath=\"@id\"/></xs:key>\n    <xs:key name=\"assetKey\"><xs:selector xpath=\"payload/sources/asset\"/><xs:field xpath=\"@id\"/></xs:key>\n    <xs:keyref name=\"anchorPageRef\" refer=\"pageKey\"><xs:selector xpath=\"payload/sources/anchor\"/><xs:field xpath=\"@pageRef\"/></xs:keyref>\n    <xs:keyref name=\"observationAnchorRef\" refer=\"anchorKey\"><xs:selector xpath=\"payload/sources/observation\"/><xs:field xpath=\"@anchorRef\"/></xs:keyref>\n    <xs:keyref name=\"revisionAnchorRef\" refer=\"anchorKey\"><xs:selector xpath=\"payload/sources/revision\"/><xs:field xpath=\"@anchorRef\"/></xs:keyref>\n    <xs:keyref name=\"revisionObservationRef\" refer=\"observationKey\"><xs:selector xpath=\"payload/sources/revision\"/><xs:field xpath=\"@observationRef\"/></xs:keyref>\n    <xs:keyref name=\"copyRevisionRef\" refer=\"revisionKey\"><xs:selector xpath=\"payload/items/copy-change\"/><xs:field xpath=\"@revisionRef\"/></xs:keyref>\n    <xs:keyref name=\"copyAnchorRef\" refer=\"anchorKey\"><xs:selector xpath=\"payload/items/copy-change\"/><xs:field xpath=\"@anchorRef\"/></xs:keyref>\n    <xs:keyref name=\"copyObservationRef\" refer=\"observationKey\"><xs:selector xpath=\"payload/items/copy-change\"/><xs:field xpath=\"@observationRef\"/></xs:keyref>\n    <xs:keyref name=\"designObservationRef\" refer=\"observationKey\"><xs:selector xpath=\"payload/items/design-task\"/><xs:field xpath=\"@observationRef\"/></xs:keyref>\n    <xs:keyref name=\"designAssetRef\" refer=\"assetKey\"><xs:selector xpath=\"payload/items/design-task\"/><xs:field xpath=\"@assetRef\"/></xs:keyref>\n  </xs:element>\n</xs:schema>\n";
